import { describe, expect, it } from 'vitest';
import type { MatchPlayer, PlayerProfile } from '../contracts/game';
import type { Course, Hole } from '../courses/types';
import { GameplayStateMachine } from './StateMachine';
import { HoleSystem } from './HoleSystem';
import { MatchManager } from './MatchManager';
import { ScoreManager } from './ScoreManager';

const makeHole = (id: string, par = 3): Hole => ({
  id, name: id, par,
  spawn: { x: 0, y: 0, z: 0 },
  cup: { position: { x: 5, y: 0, z: 0 }, radius: 0.3, captureDepth: 0.25 },
  bounds: { min: { x: -2, y: -2, z: -2 }, max: { x: 10, y: 3, z: 2 } },
  surfaces: [], obstacles: [],
});

const makePlayer = (id: string): PlayerProfile => ({
  id, displayName: id, kind: 'human', ballStyleId: 'default', rating: 1000,
});

const course: Course = {
  id: 'c1', name: 'Course', themeId: 'test', version: 1,
  holes: [makeHole('h1'), makeHole('h2', 4)],
};

describe('ScoreManager', () => {
  it('tracks strokes, penalties, max-shots and PAR labels', () => {
    const manager = new ScoreManager();
    let score = manager.createHoleScore('p1', 'h1');
    score = manager.recordStroke(score);
    score = manager.addPenalty(score);
    expect(score.strokes).toBe(2);
    expect(score.penaltyStrokes).toBe(1);
    expect(manager.parLabel(1, 3)).toBe('HOLE IN ONE');
    expect(manager.parLabel(2, 3)).toBe('BIRDIE');
    expect(manager.parLabel(3, 3)).toBe('PAR');
    expect(manager.parLabel(4, 3)).toBe('BOGEY');
    expect(manager.applyStrokeLimit({ ...score, strokes: 5 }, 5).completed).toBe(true);
  });

  it('sorts tied match results deterministically', () => {
    const manager = new ScoreManager();
    const players: MatchPlayer[] = [
      { ...makePlayer('slow'), connected: true, totalStrokes: 0, holeScores: [{ playerId: 'slow', holeId: 'h1', strokes: 3, completed: true, penaltyStrokes: 0, completionTimeMs: 9000 }] },
      { ...makePlayer('fast'), connected: true, totalStrokes: 0, holeScores: [{ playerId: 'fast', holeId: 'h1', strokes: 3, completed: true, penaltyStrokes: 0, completionTimeMs: 5000 }] },
      { ...makePlayer('penalty'), connected: true, totalStrokes: 0, holeScores: [{ playerId: 'penalty', holeId: 'h1', strokes: 3, completed: true, penaltyStrokes: 1, completionTimeMs: 1000 }] },
    ];
    expect(manager.standings(players).map(row => row.playerId)).toEqual(['fast', 'slow', 'penalty']);
  });
});

describe('HoleSystem', () => {
  it('requires low speed for capture and resets hazard to last safe position', () => {
    const system = new HoleSystem(1.2);
    const hole = makeHole('h1');
    expect(system.isBallHoled(hole, { x: 5.1, y: 0, z: 0 }, 0.5)).toBe(true);
    expect(system.isBallHoled(hole, { x: 5.1, y: 0, z: 0 }, 2)).toBe(false);
    system.setInitialSafePosition('p1', hole.spawn);
    system.markSafePosition('p1', { x: 2, y: 0, z: 0 });
    expect(system.resolveHazard('p1', hole)).toEqual({ playerId: 'p1', resetPosition: { x: 2, y: 0, z: 0 }, penaltyStrokes: 1 });
  });
});

describe('GameplayStateMachine', () => {
  it('enforces transitions and restores phase after pause', () => {
    const machine = new GameplayStateMachine();
    machine.transition('hole-intro');
    machine.transition('aiming');
    expect(machine.pause()).toBe('paused');
    expect(machine.resume()).toBe('aiming');
    expect(() => machine.transition('match-results')).toThrow(/Invalid match phase transition/);
  });
});

describe('MatchManager', () => {
  it('advances holes and finishes match', () => {
    const manager = new MatchManager();
    let match = manager.createMatch('m1', { courseId: 'c1', maxPlayers: 2, strokeLimitPerHole: 8 }, [makePlayer('p1')]);
    match = manager.startMatch(match, course, 1000);
    match = manager.beginAiming(match, course.holes[0]!);
    match = manager.markShotSubmitted(match);
    match = manager.applySimulationEvent(match, course, { type: 'shot-accepted', command: { playerId: 'p1', holeId: 'h1', direction: { x: 1, y: 0, z: 0 }, normalizedPower: .5, clientSequence: 1, issuedAt: 1000 } }, 1100);
    match = manager.applySimulationEvent(match, course, { type: 'ball-holed', playerId: 'p1', holeId: 'h1', strokes: 1 }, 1500);
    expect(match.phase).toBe('hole-intro');
    expect(match.currentHoleIndex).toBe(1);

    match = manager.beginAiming(match, course.holes[1]!);
    match = manager.markShotSubmitted(match);
    match = manager.applySimulationEvent(match, course, { type: 'shot-accepted', command: { playerId: 'p1', holeId: 'h2', direction: { x: 1, y: 0, z: 0 }, normalizedPower: .5, clientSequence: 2, issuedAt: 1600 } }, 1600);
    match = manager.applySimulationEvent(match, course, { type: 'ball-holed', playerId: 'p1', holeId: 'h2', strokes: 1 }, 2000);
    expect(match.phase).toBe('match-results');
    expect(match.finishedAt).toBe(2000);
    expect(match.players[0]?.totalStrokes).toBe(2);
  });
});
